/**
* An Identifier that must be locally unique within the containing TabSet.
*/
type TabName = Identifier;


/**
*/
type PreserveOpenState = 
/**
* Never try to automatically preserve the openState. Nodes will be initially open 
*  or closed based solely on the Tree.openProperty optionally set by the server.
*/
"never" |

/**
* If either the Tree.idField or Tree.nameProperty has been set on 
*  the Tree, (so that nodes have either unique ids or unique paths), 
*  preserve openState by respecting the Tree.openProperty set by the server, 
*  then applying the openState.
*/
"whenUnique" |

/**
* Like "whenUnique" but automatically preserves openState even if nodes cannot be
*  uniquely identified. This means that nodes at the same tree positions 
*  (eg 3rd child of 5th node under root) will be placed in the same openState, 
*  regardless of whether that node has anything to do with the node that previously 
*  was at that tree position.
*/
"always";


/**
* What kind of mask to use for masking dragged element.
*/
type DragMaskType = 
/**
* creates an element with ordinary HTML content that will block events
*/
"div" |

/**
* creates an iframe with empty content
*/
"iframe" |

/**
* hides the contents of this widget temporarily
*/
"hide" |

/**
* no mask
*/
"none";




/**
*/
type Alignment = 
/**
* Center within container.
*/
"center" |

/**
* Stick to left side of container.
*/
"left" |

/**
* Stick to right side of container.
*/
"right";




/**
* This string is the base CSS class name applied to a FormItem (or some part of a form item). 
*  See the formItemStyling for more information about
*  styling formItems.
*  
*  The specified style name will be modified as the 'state' of the form item changes. 
*  Developers should provide appropriately named CSS classes for each stateful style
*  described below:
*  
* - If FormItem.showPending is true, when the current value differs from the
*    value that would be restored by a call to DynamicForm.resetValues, this style
*    will have the suffix "Pending" appended to it.
*  
* - If FormItem.showFocused is true, when the form item receives focus, this
*    style will have the suffix "Focused" appended to it.
*  
* - If FormItem.showOver is true, roll-over will be indicated by appending the
*    suffix "Over" appended to the style name. This applies to the
*    FormItem.textBoxStyle and
*    FormItem.controlStyle only.
*  
* - If FormItem.showErrorStyle is true, if the form item has errors, this
*    style will have the suffix "Error" appended to it.
*  
* - If FormItem.showDisabled is true, when the form item is disabled, this
*    style will have the suffix "Disabled" appended to it.
*  
* - Finally, if FormItem.showRTL is true, when the form item is in RTL mode, this
*    style will have the suffix "RTL" appended to it.
*  So for example if the cellStyle for some form item is set to "formCell" and showFocused
*  is true, when the form item receives focus, the form item's cell will have the "formCellFocused"
*  style applied to it.
*/
type FormItemBaseStyle = string;






/**
* Facet value definition object made use of by the CubeGrid and
*  FacetChart classes (contained by facets).
*/
class FacetValue {


/**
* id of this facetValue. Any string or number.
* @type {string | number}
* @default null
*/
id: string | number;

/**
* User-visible title of this facetValue. Shown on the field header.
* @type {string}
* @default null
*/
title: string;

/**
* For tree facets (Facet.isTree), id of this facetValue's
*  parent facetValue.
*  
*  Note: This property is specific to CubeGrid.
* @type {string | number}
* @default null
*/
parentId: string | number;

/**
* Whether cells for this facetValue can be edited. Defaults to CubeGrid.canEdit.
*  
*  Note: This property is specific to CubeGrid.
* @type {boolean}
* @default "cubeGrid.canEdit"
*/
canEdit: boolean;

/**
* For tree facets, initial collapse state for this node. Defaults to Facet.collapsed.
*  
*  Note: This property is specific to CubeGrid.
* @type {boolean}
* @default "facet.collapsed"
*/
collapsed: boolean;

/**
* For individual parent facetValues within a hierarchical facet, this flag controls
*  whether an expand/collapse control will be shown.
*  
*  Note: This property is specific to CubeGrid (see, for
*  example, CubeGrid.canCollapseFacets).
* @type {boolean}
* @default true
*/
canCollapse: boolean;

/**
* Used to determine which facetValue is to be shown when the facet is minimized.
*  
*  Note: This property is specific to CubeGrid. See
*  CubeGrid.canMinimizeFacets.
* @type {boolean}
* @default false
*/
isMinimizeValue: boolean;

/**
* Width of the cube grid facetValue in pixels.
*  
*  Note: This property is specific to CubeGrid.
* @type {number}
* @default "facet.width"
*/
width: number;

/**
* Default alignment for facet label title and cells for this facetValue.
*  Can be overridden by setting titleAlign or cellAlign on the facetValue.
*  
*  Note: This property is specific to CubeGrid (see, for
*  example, CubeGrid.facetValueAlign).
* @type {Alignment}
* @default null
*/
align: Alignment;

/**
* Default alignment of cells (in the body) for this facetValue.
*  
*  Note: This property is specific to CubeGrid (see, for
*  example, CubeGrid.cellAlign).
* @type {Alignment}
* @default "facet.cellAlign"
*/
cellAlign: Alignment;

/**
* CSS line style to apply as a border before this facetValue.
*  
*  Note: This property is specific to CubeGrid.
* @type {string}
* @default null
*/
borderBefore: string;

/**
* CSS line style to apply as a border after this facetValue.
*  
*  Note: This property is specific to CubeGrid.
* @type {string}
* @default null
*/
borderAfter: string;

/**
* Selection boundary determining what facets / facetValues can be selected together by
*  drag selection / shift+click selection.
*  
*  Note: This property is specific to CubeGrid.
* @type {SelectionBoundary}
* @default null
*/
selectionBoundary: SelectionBoundary;

/**
* Hilite style to apply to the title for this facetValue.
*  
*  Note: This property is specific to CubeGrid. See
*  CubeGrid.hilites.
* @type {string}
* @default null
*/
titleHilite: string;







/**
*  Callout to determine custom value to display for cells displayed for this facetValue.
*  
*  Can only be set on the CubeGrid.metricFacetId or, if no metric facet
*  is specified, on the innermost column facet.
*  
*  Note: This method is specific to CubeGrid.
* 
* 
* @param {CubeGrid} this facetValue's CubeGrid
* @param {object} cell record
* @param {number} row value for the cell
* @param {number} column value for the cell
*/
getCellValue(viewer:CubeGrid, record:object, rowNum:number, colNum:number): string;

/**
*  Formatter to apply to values displayed for cells under this facetValue.
*  
*  Can only be set on the CubeGrid.metricFacetId or, if no metric facet
*  is specified, on the innermost column facet.
*  
*  If a single, grid-wide formatting style is desired, implement
*  ListGrid.formatCellValue instead.
*  
*  Note: This method is specific to CubeGrid.
* 
* 
* @param {any} raw value for the cell being
* @param {CellRecord} record object for the cell.  Note: If this is a new cell that has not been saved, in an   editable grid, it has no associated record object. In this case the edit values will  be passed in as this parameter.
* @param {number} row number for the cell
* @param {number} column number for the cell.
*/
formatCellValue(value:any, record:CellRecord, rowNum:number, colNum:number): string;




}

/**
* Every node in the tree is represented by a TreeNode object which is an object literal with a
*  set of properties that configure the node.
*  
*  When a Tree is supplied as TreeGrid.data to TreeGrid, you can also set
*  properties from ListGridRecord on the TreeNode (e.g. setting
*  ListGridRecord.enabled:false on the node).
*/
class TreeNode {


/**
* Default property name denoting whether this record is enabled. Property name may be
*  modified for some grid via ListGrid.recordEnabledProperty.
* @type {boolean}
* @default null
*/
enabled: boolean;

/**
* Governs whether this node can be dragged. Only has an effect if this node is displayed in
*  a TreeGrid where TreeGrid.canDragRecordsOut, TreeGrid.canReorderRecords
*  or TreeGrid.canReparentNodes is true.
* @type {boolean}
* @default null
*/
canDrag: boolean;

/**
* Governs whether dragged data (typically other treeNodes) may be dropped over
*  this node. Only has an effect if this node is displayed in a TreeGrid where
*  TreeGrid.canAcceptDroppedRecords, TreeGrid.canReorderRecords or 
*  TreeGrid.canReparentNodes is true.
* @type {boolean}
* @default null
*/
canAcceptDrop: boolean;

/**
* Set to true or a string that is not equal to (ignoring case)
*  "false" to explicitly mark this node as a folder. See Tree.isFolder for
*  a full description of how the Tree determines whether a node is a folder or not.
*  
*  Note: the name of this property can be changed by setting Tree.isFolderProperty.
* @type {boolean | string}
* @default null
*/
isFolder: boolean | string;

/**
* Provides a name for the node that is unique among its immediate siblings, thus allowing a
*  unique path to be used to identify the node, similar to a file system. See
*  Tree.getPath.
*  
*  If the nameProperty is not set on a given node, the TreeNode.id will be used instead. If
*  this is also missing, Tree.getName and Tree.getPath will auto-generate a
*  unique name for you. Thus names are not required, but if the dataset you are using already
*  has usable names for each node, using them can make APIs such as Tree.find more
*  useful. Alternatively, if your dataset has unique ids consider providing those as
*  TreeNode.id.
*  
*  If a value provided for the nameProperty of a node (e.g. node.name) is not a
*  string, it will be converted to a string by the Tree via ""+value.
*  
*  This property is also used as the default title for the node (see Tree.getTitle)
*  if TreeNode.title is not specified.
*  
*  Note: the name of this property can be changed by setting Tree.nameProperty.
* @type {string}
* @default "null, but see below"
*/
name: string;

/**
* The title of the node as it should appear next to the node icon in the Tree. If left
*  unset, the value of TreeNode.name is used by default. See the description in
*  Tree.getTitle for full details.
*  
*  Note: the name of this property can be changed by setting Tree.titleProperty.
* @type {HTMLString}
* @default null
*/
title: HTMLString;

/**
* Specifies the unique ID of this node. 
*  
*  Required for trees with Tree.modelType "parent". With modelType:"parent", the unique
*  ID of a node, together with the unique ID of its parent (see TreeNode.parentId) is
*  used by Tree.linkNodes to link a list of nodes into a tree.
*  
*  Note: the name of this property can be changed by setting Tree.idField.
* @type {string | number}
* @default null
*/
id: string | number;

/**
* For trees with modelType:"parent", this property specifies the unique ID of this node's 
*  parent node.
*  The unique ID of a node, together with the unique ID of its parent is used by
*  Tree.linkNodes to link a list of nodes into a tree.
*  
*  Note: the name of this property can be changed by setting Tree.parentIdField.
* @type {string | number}
* @default null
*/
parentId: string | number;

/**
* For trees with the modelType "children", this property specifies the children of this
*  TreeNode.
*  
*  Note: the name of this property can be changed by setting Tree.childrenProperty
* @type {Array<Partial<TreeNode>>}
* @default null
*/
children: Array<Partial<TreeNode>>;

/**
* This Property allows the developer to customize the icon displayed next to a node.
*  Set node.icon to the URL of the desired icon to display and
*  it will be shown instead of the standard TreeGrid.nodeIcon for this node.
*  Note that if TreeNode.showOpenIcon and/or TreeNode.showDropIcon 
*  is true for this node, customized icons for folder nodes will be appended with the 
*  TreeGrid.openIconSuffix or TreeGrid.dropIconSuffix suffixes on state change 
*  as with the standard TreeGrid.folderIcon for this treeGrid. Also note that for
*  custom folder icons, the TreeGrid.closedIconSuffix will never be appended.
*  You can change the name of this property by setting 
*  TreeGrid.customIconProperty.
* @type {SCImgURL}
* @default null
*/
icon: SCImgURL;

/**
* For folder nodes showing custom icons (set via TreeNode.icon),
*  this property allows the developer to specify on a per-node basis whether an
*  open state icon should be displayed when the folder is open.
*  Set node.showOpenIcon to true to show the open state
*  icons, or false to suppress this.
*  If not specified, this behavior is determined by TreeGrid.showCustomIconOpen
*  for this node.
*  You can change the name of this property by setting 
*  TreeGrid.customIconOpenProperty.
* @type {boolean}
* @default false
*/
showOpenIcon: boolean;

/**
* For folder nodes showing custom icons (set via TreeNode.icon),
*  this property allows the developer to specify on a per-node basis whether a
*  drop state icon should be displayed when the 
*  user drop-hovers over this folder.
*  Set node.showDropIcon to true to show the drop state
*  icon, or false to suppress this.
*  If not specified, this behavior is determined by TreeGrid.showCustomIconDrop
*  for this node.
*  You can change the name of this property by setting 
*  TreeGrid.customIconDropProperty.
* @type {boolean}
* @default false
*/
showDropIcon: boolean;

/**
* For folder nodes showing custom icons (set via TreeNode.icon),
*  this property allows the developer to specify on a per-node basis whether a
*  selected state icon should be displayed when the folder is open.
*  Set node.showSelectedIcon to true to show the selected state
*  icons, or false to suppress this.
*  If not specified, this behavior is determined by TreeGrid.showCustomIconSelected
*  for this node.
*  You can change the name of this property by setting 
*  TreeGrid.customIconSelectedProperty.
* @type {boolean}
* @default false
*/
showSelectedIcon: boolean;










}



