/**
* Shows an interface allowing a user to create or edit fields by typing simple
*  format-strings into a text field. The format-strings can include the values of other fields
*  and additional text as required.
*  
*  Available values for the format-string are determined by the DataSource fields, and are given
*  simple single-letter aliases (such as "A", "B", ...) similar to column names in Excel.
*  The set of available values is shown in the FormulaBuilder.fieldKey as a simple
*  mapping between the DataSourceField.title and it's short name.
*  
*  To include a field in the format-string, prefix it with a hash sign (#).
*/
class SummaryBuilder extends FormulaBuilder {
/**
* Creates a new SummaryBuilder
* 
* @param typeCheckedProperties {Partial<SummaryBuilder>=} Object literal containing init properties that will be checked against the class field types.
* @param uncheckedProperties {Object} Object literal containing init properties that will not be checked against the class field types.
* @return {SummaryBuilder} The new instance
*/
static create(typeCheckedProperties? : Partial<SummaryBuilder>, uncheckedProperties?: Object): SummaryBuilder;


/**
* Indicates whether to use "summary" or some other keyword in various captions and text
* @type {string}
* @default "Summary"
*/
builderTypeText: string;

/**
* DataSource providing the available fields for the formulaBuilder.
*  
*  By default the formulaBuilder will include only fields of numeric type or derived
*  from a numeric type. Set FormulaBuilder.fields to override this.
* @type {DataSource | GlobalId}
* @default null
*/
dataSource: DataSource | GlobalId;

/**
* DataSource providing the available fields for the SummaryBuilder.
*  
*  By default the SummaryBuilder will include all fields. Set SummaryBuilder.fields to 
*  override this.
* @type {Array<Partial<string>>}
* @default null
*/
fields: Array<Partial<string>>;

/**
* Are we editing an existing field?
* @type {boolean}
* @default false
*/
editMode: boolean;

/**
* The Field object representing the field being created or edited.
* @type {string}
* @default null
*/
field: string;

/**
* TextItem that users type into when entering a formula.
* @type {TextItem}
* @default null
*/
formulaField: TextItem;

/**
* TextItem that allows users to set the title for this field.
* @type {TextItem}
* @default null
*/
titleField: TextItem;

/**
* Whether to show the help icon that appears after the SummaryBuilder.formulaField.
* @type {boolean}
* @default true
*/
showHelpIcon: boolean;

/**
* Icon that appears after the SummaryBuilder.formulaField, showing help on hover.
* @type {FormItemIcon}
* @default null
*/
helpIcon: FormItemIcon;

/**
* Whether to show a checkbox offering the user the ability to automatically
*  hide any fields involved in the formula.
* @type {boolean}
* @default true
*/
showAutoHideCheckBox: boolean;

/**
* CheckBox that, when selected, hides columns in the component that are used in this formula.
* @type {TextItem}
* @default null
*/
autoHideCheckBox: TextItem;

/**
* Record to use when showing sample output for the format string.
*  
*  If not specified, the selected record in the component that launched the SummaryBuilder will
*  be used, or if there's no selection, the first visible row, or with no component, a dummy
*  data row derived automatically from the provided DataSource.
* @type {Record}
* @default null
*/
testRecord: Record;

/**
* Text label for the checkbox that allows the user to automatically hide the
*  fields used in the summary format.
* @type {string}
* @default "Auto hide fields used in summary"
*/
autoHideCheckBoxLabel: string;

/**
* Text that appears in the hover from the SummaryBuilder.helpIcon, as a pre-amble to the list of
*  available format-tokens.
* @type {string}
* @default "Building Summary Columns"
*/
helpTextIntro: string;







/**
*  Call to set the format-string in this SummaryBuilder.
*  
*  Note that calling setSummary() will update the UI, generate the summary's function and 
*  test it automatically.
* 
* 
* @param {string} The new format-string for the summary
*/
setSummary(newValue:string): void;

/**
*  Call to retrieve the text the SummaryBuilder would show by default for help, or override to
*  provide alternate help text.
* 
* 
*/
getHelpText(): string;

/**
*  Override to execute a callback function when the Format is Cancelled or Saved.
*  
* 
*/
fireOnClose(): void;

/**
*  Call to finish working, test the formula and call 
*  FormulaBuilder.fireOnClose. Called automatically
*  when the Save button is clicked.
* 
* 
*/
save(): void;




}

/**
* A MultiComboBoxItem is a combo box that allows the user to select multiple options. Each
*  selected option is represented as a button that can be clicked to deselect the option.
* 
*  The relative layout of the buttons to the combo box is specified with the
*  MultiComboBoxItem.layoutStyle attribute. The buttons will be kept in the order that
*  they were added, with the most recently added button being adjacent to the combo box.
* 
*  MultiComboBoxItem uses the AutoChild pattern to construct the
*  MultiComboBoxItem.comboBox and the MultiComboBoxItem.button
*  so that they can be easily customized. For example, you can customize the criteria used to
*  fetch by
*  overriding ComboBoxItem.getPickListFilterCriteria via
*  MultiComboBoxItem.comboBox.
*  
*/
class MultiComboBoxItem extends CanvasItem {
/**
* Creates a new MultiComboBoxItem
* 
* @param typeCheckedProperties {Partial<MultiComboBoxItem>=} Object literal containing init properties that will be checked against the class field types.
* @param uncheckedProperties {Object} Object literal containing init properties that will not be checked against the class field types.
* @return {MultiComboBoxItem} The new instance
*/
static create(typeCheckedProperties? : Partial<MultiComboBoxItem>, uncheckedProperties?: Object): MultiComboBoxItem;
/**
* The default hint string.
* @type {string}
* @default "Enter values"
*/
static defaultHint: string;



/**
* Should this item's value be saved in the form's values and hence returned from
*  DynamicForm.getValues?
*  
*  shouldSaveValue:false is used to mark formItems which do not correspond to
*  the underlying data model and should not save a value into the form's
*  DynamicForm.values. Example includes visual separators, password re-type fields,
*  or checkboxes used to show/hide other form items.
*  
*  A shouldSaveValue:false item should be given a value either via
*  FormItem.defaultValue or by calling
*  DynamicForm.setValue or 
*  FormItem.setValue. Providing a value via
*  DynamicForm.values or DynamicForm.setValues 
*  will automatically switch the item to shouldSaveValue:true.
*  
*  Note that 
*  
* - if an item is shouldSaveValue true, but has no name, a warning is logged, and 
*    shouldSaveValue will be set to false.
*  
* @type {boolean}
* @default true
*/
shouldSaveValue: boolean;

/**
* The optionDataSource of the combo box.
* @type {DataSource | string}
* @default null
*/
optionDataSource: DataSource | string;

/**
* Similar to ComboBoxItem.addUnknownValues, controls whether additional values can be
*  added to the ComboBox or whether the user must choose from the available values in the picklist
*  only.
*  
*  If this setting is changed after the MultiComboBoxItem has been created, the current value of
*  the item is reset to null and all buttons for non-default values (values not in the FormItem.defaultValue
*  array) are removed.
* @type {boolean}
* @default false
*/
addUnknownValues: boolean;

/**
* If true, hitting tab always exits the field, and will also add a value to the list of
*  selected values if there is match (and depending on the setting for
*  MultiComboBoxItem.addUnknownValues).
*  
*  If false, if the user has typed in a value and hits tab, focus remains in the field.
*  If there is a match or if MultiComboBoxItem.addUnknownValues is true, a value will be added.
*  Otherwise, the input cursor remains at the end of the entered value.
* @type {boolean}
* @default true
*/
alwaysExitOnTab: boolean;

/**
* Should the MultiComboBoxItem fetch data from the MultiComboBoxItem.optionDataSource
*  immediately or wait until the user first opens the pickList.
* @type {boolean}
* @default false
*/
autoFetchData: boolean;

/**
* The valueMap of the combo box.
* @type {Array<any> | object}
* @default null
*/
valueMap: Array<any> | object;

/**
* An AutoChild attribute to create the combo box in a MultiComboBoxItem.
* @type {ComboBoxItem}
* @default null
*/
comboBox: ComboBoxItem;

/**
* The DynamicForm holding the MultiComboBoxItem.comboBox.
* @type {DynamicForm}
* @default null
*/
comboForm: DynamicForm;

/**
* If this item has a specified optionDataSource, this attribute may be set
*  to specify an explicit DSRequest.operationId when performing a fetch against the
*  option dataSource to pick up display value mapping.
* @type {string}
* @default null
*/
optionOperationId: string;

/**
* The displayField of the combo box.
* @type {string}
* @default null
*/
displayField: string;

/**
* The valueField of the combo box.
* @type {string}
* @default null
*/
valueField: string;

/**
* The layout used to arrange the MultiComboBoxItem.comboForm and the buttons
*  representing the values of the MultiComboBoxItem. Note that the constructor cannot be changed
*  (setting a valueLayoutConstructor has no effect) because the exact layout class used depends
*  on the current MultiComboBoxItem.layoutStyle.
* @type {Layout}
* @default null
*/
valueLayout: Layout;

/**
* An AutoChild attribute used to create the buttons in the MultiComboBoxItem.
* @type {IButton}
* @default null
*/
button: IButton;

/**
* When FormItem.showPending is true, the Button.baseStyle
*  used on MultiComboBoxItem.button that are in the "Pending" visual state.
*  
*  If unset, then the baseStyle of pending buttons is not changed.
* @type {CSSStyleName}
* @default "buttonPending"
*/
pendingButtonStyle: CSSStyleName;

/**
* When FormItem.showDeletions is true, the Button.baseStyle
*  used on MultiComboBoxItem.button for values that have been deleted (also called "deselected
*  buttons").
*  
*  If unset, then the baseStyle of deselected buttons is not changed.
*  
*  NOTE: Deselected buttons are also disabled, so styling should be provided
*  for the deselectedButtonStyle&nbsp;+&nbsp;"Disabled" style name.
* @type {CSSStyleName}
* @default "buttonDeselected"
*/
deselectedButtonStyle: CSSStyleName;

/**
* Specifies the layout style of the combo box and the buttons in the MultiComboBoxItem.
*  Available values are "flow" (the default), "horizontal", "horizontalReverse",
*  "vertical", and "verticalReverse".
* 
*  
*  
* - "flow":&nbsp; The buttons appear to the left of the combo box. When there is no
*  more room, the combo box and/or buttons flow onto a new line. The buttons autoFit
*  by default.
*  
* - "horizontal":&nbsp; The combo box appears on right and buttons are horizontally
*  stacked directly left of it. The buttons must autofit.
*  
* - "horizontalReverse":&nbsp; Like "horizontal" but the combo box appears on the left.
*  The buttons must autofit.
*  
* - "vertical":&nbsp; The combo box appears on top and buttons are stacked beneath it.
*  Buttons do not autofit by default.
*  
* - "verticalReverse":&nbsp; Like "vertical" but the combo box appears at bottom.
*  The buttons do not autofit by default.
*  
* @type {MultiComboBoxLayoutStyle}
* @default "flow"
*/
layoutStyle: MultiComboBoxLayoutStyle;

/**
* Specifies whether to autofit the buttons in the MultiComboBoxItem. The
*  default value is true if MultiComboBoxItem.layoutStyle is "flow", but false for a
*  layoutStyle of "vertical" or "verticalReverse". If the layoutStyle
*  is "horizontal" or "horizontalReverse" then the buttons will autofit regardless
*  of the setting of this property.
* @type {boolean}
* @default null
*/
autoFitButtons: boolean;

/**
* Specifies the size of the combo box field.
*  
*  Note that this attribute only has an effect in "flow", "horizontal", and
*  "horizontalReverse" MultiComboBoxItem.layoutStyle. In the other modes, the combo box
*  is as wide as the overall MultiComboBoxItem.
* @type {number}
* @default "130"
*/
comboBoxWidth: number;

/**
* Specifies whether to arrange the buttons of the MultiComboBoxItem in the order that they were
*  selected (the default), or to sort the buttons by MultiComboBoxItem.displayField.
* @type {boolean}
* @default true
*/
useInsertionOrder: boolean;







/**
*  This method will be called whenever this FormItem's value is being set via a programmatic
*  call to e.g: DynamicForm.setValues or FormItem.setValue and may be
*  overridden by CanvasItems intended to support displaying data values to update the
*  embedded Canvas to reflect the value passed in.
*  
*  The value of a MultiComboBoxItem to the form is an array of valueField values corresponding
*  to the selected combo box options.
* 
* @param {any} new display value for the item. This is the value after applying  any custom formatter or valueMap
* @param {any} underlying data value for the item
* @param {DynamicForm} the dynamicForm in which this item is contained
* @param {CanvasItem} the live form item instance
*/
showValue(displayValue:any, dataValue:any, form:DynamicForm, item:CanvasItem): void;

/**
* @param {MultiComboBoxLayoutStyle} the new layout style
*/
setLayoutStyle(layoutStyle:MultiComboBoxLayoutStyle): void;

/**
*  Sets the MultiComboBoxItem.autoFitButtons property.
* 
* @param {boolean} whether to autofit the buttons
*/
setAutoFitButtons(autoFitButtons:boolean): void;

/**
*  Notification method called when FormItem.showPending is enabled and this
*  MultiComboBoxItem should either clear or show its pending visual state.
*  
*  The default behavior is that the FormItem.titleStyle and
*  FormItem.cellStyle are updated to include/exclude the "Pending" suffix.
*  In addition, when displayed in the pending state and a
*  MultiComboBoxItem.pendingButtonStyle is set, then:
*  
*  
* - If MultiComboBoxItem.useInsertionOrder is false, buttons for
*    any new values will have their Button.baseStyle set to
*    pendingButtonStyle; otherwise
*  
* - (useInsertionOrder is true) buttons for values will have their
*    Button.baseStyle set to pendingButtonStyle if either the
*    value is new or it is in a different place within the value array.
*  
*  Returning false will cancel this default behavior.
* 
* @param {DynamicForm} the managing DynamicForm instance.
* @param {FormItem} the form item itself (also available as "this").
* @param {boolean} true if the item should show its pending visual state; false otherwise.
* @param {any} the current form item value.
* @param {any} the value that would be restored by a call to DynamicForm.resetValues.
*/
pendingStatusChanged(form:DynamicForm, item:FormItem, pendingStatus:boolean, newValue:any, value:any): boolean;




}



/**
* The StretchImg widget class implements a widget type that displays a list of multiple images
*  that make up a single image.
*/
class StretchImg extends StatefulCanvas {
/**
* Creates a new StretchImg
* 
* @param typeCheckedProperties {Partial<StretchImg>=} Object literal containing init properties that will be checked against the class field types.
* @param uncheckedProperties {Object} Object literal containing init properties that will not be checked against the class field types.
* @return {StretchImg} The new instance
*/
static create(typeCheckedProperties? : Partial<StretchImg>, uncheckedProperties?: Object): StretchImg;


/**
* Indicates whether the list of images is drawn vertically from top to bottom (true),
*  or horizontally from left to right (false).
* @type {boolean}
* @default true
*/
vertical: boolean;

/**
* If the default items are used, capSize is the size in pixels of the first and last
*      images in this stretchImg.
* @type {number}
* @default "2"
*/
capSize: number;

/**
* The base URL for the image. 
*  
*  The State for the component will be combined with this URL using the
*  same approach as described in Img.src.
*  Then the image segment StretchItem.name as specified by each StretchItem
*  is added.
*  
*  For example, for a stretchImg in "Over" state with a src of "button.png"
*  and a segment name of "stretch", the resulting URL would be "button_Over_stretch.png".
* @type {SCImgURL}
* @default null
*/
src: SCImgURL;

/**
* Base URL for the image if StretchImg.vertical is false and 
*  StretchImg.src is unset.
* @type {SCImgURL}
* @default null
*/
hSrc: SCImgURL;

/**
* Base URL for the image if StretchImg.vertical is true and 
*  StretchImg.src is unset.
* @type {SCImgURL}
* @default null
*/
vSrc: SCImgURL;

/**
* Indicates whether the image should be tiled/cropped, stretched, or centered when the
*      size of this widget does not match the size of the image. See ImageStyle for
*      details.
* @type {ImageStyle}
* @default "stretch"
*/
imageType: ImageStyle;

/**
* The list of images to display as an array of objects specifying the image names and
*  sizes.
*  
*  The StretchItem.name is appended as a suffix to the StretchImg.src URL in order
*  to fetch separate media files for each image. Alternatively a StretchItem may specify
*  its own StretchItem.src.
*  
*  The StretchItem.height and StretchItem.width can be set to a number,
*  "*" (remaining space, divided amongst all images that specify "*") or to the name of a
*  property on this StretchImg component, such as "capSize" for the StretchImg.capSize.
*  
*  Height or width is only used for the axis along which images are stacked. For example, if
*  StretchImg.vertical is true, images stack vertically and heights are used to size images on
*  the vertical axis, but all images will have width matching the overall component size.
*  
*  For example, the default setting for items, which is used to produce
*  stretchable buttons and headers with fixed-size endcaps, is as follows:
*  
*   items:[
*     {height:"capSize", name:"start", width:"capSize"},
*     {height:"*", name:"stretch", width:"*"},
*     {height:"capSize", name:"end", width:"capSize"}
*   ]
*  
*  Note that by default horizontal StretchImg instances will always render their items
*  in left-to-right order, even if the page is localized for right-to-left display
*  (see Page.isRTL). This default behavior may be overridden by setting the
*  StretchImg.ignoreRTL flag to false.
* @type {Array<Partial<StretchItem>>}
* @default "see below"
*/
items: Array<Partial<StretchItem>>;

/**
* Should the StretchImg.items for this StretchImg display left-to-right even
*  if this page is displaying Page.isRTL?
*  
*  Only has an effect if this StretchImg is horizontal (StretchImg.vertical
*  is set to false).
*  
*  Having this property set to true is usually desirable for the common pattern of media
*  consisting of fixed size "end caps" and a stretchable center, because it allows the same
*  media to be used for LTR and RTL pages.
*  
*  If set to false, items will be displayed in RTL order for RTL pages.
* @type {boolean}
* @default true
*/
ignoreRTL: boolean;

/**
* Should we show a "grip" image floating above the center of this widget?
* @type {boolean}
* @default null
*/
showGrip: boolean;

/**
* Suffix used the 'grip' image if StretchImg.showGrip is true.
* @type {string}
* @default "grip"
*/
gripImgSuffix: string;

/**
* If StretchImg.showGrip is true, this property determines whether to show the
*  'Down' state on the grip image when the user mousedown's on this widget. 
*  Has no effect if StatefulCanvas.showDown is false.
* @type {boolean}
* @default null
*/
showDownGrip: boolean;

/**
* If StretchImg.showGrip is true, this property determines whether to show the
*  'Over' state on the grip image when the user rolls over on this widget. 
*  Has no effect if StatefulCanvas.showRollOver is false.
* @type {boolean}
* @default null
*/
showRollOverGrip: boolean;

/**
* Determines whether any specified StatefulCanvas.getTitle will be 
*  displayed for this component.
*  Applies to Image-based components only, where the title will be rendered out in a label
*  floating over the component
* @type {boolean}
* @default false
*/
showTitle: boolean;

/**
* If specified this css class will be applied to the individual item images within this StretchImg.
*  May be overridden by specifying item-specific base styles to each object in the
*  StretchImg.items. This base style will have standard stateful suffixes
*  appended to indicate the state of this component (as described in 
*  StatefulCanvas.baseStyle).
* @type {CSSStyleName}
* @default null
*/
itemBaseStyle: CSSStyleName;







/**
*  Set the specified image's state to newState and update the displayed image given by
*  whichPart, or set the state for all images to newState and update the displayed images
*  if whichPart is not provided.
* 
* @param {string} name for the new state ("off", "down", etc)
* @param {string=} name of the piece to set ("start", "stretch" or "end")     	if not specified, sets them all
*/
setState(newState:string, whichPart?:string): void;

/**
*  Changes the base StretchImg.src for this stretchImg, redrawing if necessary.
* 
* 
* @param {SCImgURL} new URL for the image
*/
setSrc(src:SCImgURL): void;

/**
*  Setter for StretchImg.items.
* 
* @param {Array<Partial<StretchItem>>} the new array of items.
*/
setItems(items:Array<Partial<StretchItem>>): void;

/**
*  Setter for StretchImg.ignoreRTL.
* 
* @param {boolean} new value for ignoreRTL.
*/
setIgnoreRTL(ignoreRTL:boolean): void;




}

