/**
* Priority levels for log messages
*/
type LogPriority = 
/**
* unrecoverable error
*/
1 |

/**
* error, may be recoverable
*/
2 |

/**
* apparent problem, misused API, partial result
*/
3 |

/**
* significant events in normal operation
*/
4 |

/**
* diagnostics for developers
*/
5;






/**
* Behavior of selection when row spanning is active. See ListGrid.useRowSpanStyling.
*/
type RowSpanSelectionMode = 
/**
* when a cell is clicked on, select any cells in subsequent columns which         are at least partially spanned by the clicked cell
*/
"forward" |

/**
* when a cell is clicked on, selects any cells in any other columns which         are at least partially spanned by the clicked cell
*/
"both" |

/**
* behaves like "forward", except as though the cell in the first column          was clicked instead. If the largest row spans are in the first
*           column and all cells in subsequent columns do not extend out of the
*           first cell's span, this creates a row-like selection model where the
*           span of the left-most cell defines the "row" of cells being selected.
*/
"outerSpan";




/**
* A component that connects to a database (and, depending on the RDBMS in use, optionally a 
*  particular catalog and/or schema) and displays the currently-defined tables, optionally 
*  filtered in a variety of ways. It also allows you to view the column details
*  of a selected table, and optionally retrieves and displays the data currently in that table.
*  
*  The DatabaseBrowser can also create a SmartClient DataSource from any existing SQL table.
*/
class DatabaseBrowser extends Window {
/**
* Creates a new DatabaseBrowser
* 
* @param typeCheckedProperties {Partial<DatabaseBrowser>=} Object literal containing init properties that will be checked against the class field types.
* @param uncheckedProperties {Object} Object literal containing init properties that will not be checked against the class field types.
* @return {DatabaseBrowser} The new instance
*/
static create(typeCheckedProperties? : Partial<DatabaseBrowser>, uncheckedProperties?: Object): DatabaseBrowser;


/**
* The type of database server this DatabaseBrowser should connect to. Valid values are 
*  "sql" (SmartClient's own built-in support for SQL databases) or "hibernate"
* @type {string}
* @default "sql"
*/
serverType: string;

/**
* The name of the database configuration to use. Database configurations are set up 
*  through the "Databases" tab of the Developer Console. If not set, defaults to the 
*  current default database configuration.
*  
*  Note that this property only applies where DatabaseBrowser.serverType is "sql"
* @type {string}
* @default null
*/
dbName: string;

/**
* The name of the database catalog to use, if the RDBMS in use recognizes the concept of
*  multiple catalogs. Leave this property unset to include all catalogs.
*  
*  Note that this property only applies where DatabaseBrowser.serverType is "sql"
* @type {string}
* @default null
*/
catalog: string;

/**
* The name of the database schema to use. Leave this property unset to include all 
*  schemata. Note that this property is not applicable to the MySQL database, which
*  does not recognize the concept of multiple schemata within a database.
*  
*  Note that this property only applies where DatabaseBrowser.serverType is "sql"
* @type {string}
* @default null
*/
schema: string;

/**
* Instance of TreeGrid used to display the database schema (tables and columns)
* @type {ListGrid}
* @default null
*/
schemaTree: ListGrid;

/**
* Instance of DynamicForm used to select a database from the list for display in the 
*  DatabaseBrowser.schemaTree.
* @type {ListGrid}
* @default null
*/
databaseList: ListGrid;

/**
* Instance of ListGrid used to display the actual data in the table selected in the 
*  DatabaseBrowser.schemaTree.
* @type {ListGrid}
* @default null
*/
dataGrid: ListGrid;

/**
* Instance of Button used to continue once a table has been selected.
* @type {Button}
* @default null
*/
selectButton: Button;

/**
* A title to show in the header button of the DatabaseBrowser's schema tree. If not set,
*  defaults to the name of the connected database
* @type {string}
* @default null
*/
title: string;

/**
* If set, specifies a substring which must exist in a table name for it to be included in
*  this DatabaseBrowser. If this property is set to a List of strings, table names are
*  included if they match any one of the strings. The comparison is case-insensitive.
*  
*  For example, includeSubstring: ["E", "qry"] would match all the following 
*  table names: "table", "QryTbl", "QRY", "ORDERS"
* @type {string | Array<Partial<string>>}
* @default null
*/
includeSubstring: string | Array<Partial<string>>;

/**
* If set, specifies a substring which must NOT exist in a table name for it to be included in
*  this DatabaseBrowser. If this property is set to a List of strings, table names are
*  excluded if they match any one of the strings. The comparison is case-insensitive.
*  
*  For example, excludeSubstring: ["E", "qry"] would exclude all the following 
*  table names: "table", "QryTbl", "QRY", "ORDERS"
*  
*  Note that if you specify both include and exclude criteria and they conflict (ie,
*  according to the criteria you set, a table should be both included and excluded), 
*  exclude wins.
* @type {string | Array<Partial<string>>}
* @default null
*/
excludeSubstring: string | Array<Partial<string>>;







/**
*  Returns the DataSource most recently auto-derived by this DatabaseBrowser. This will
*  correspond to the currently-selected table.
* 
*/
getGeneratedDataSource(): void;

/**
*  
* 
*/
getResults(): void;




}

/**
* DrawItem subclass to render Pie Slices.
*/
class DrawSector extends DrawItem {
/**
* Creates a new DrawSector
* 
* @param typeCheckedProperties {Partial<DrawSector>=} Object literal containing init properties that will be checked against the class field types.
* @param uncheckedProperties {Object} Object literal containing init properties that will not be checked against the class field types.
* @return {DrawSector} The new instance
*/
static create(typeCheckedProperties? : Partial<DrawSector>, uncheckedProperties?: Object): DrawSector;


/**
* DrawSector only supports the
*  "move"
*  
*  knob type.
* @type {Array<Partial<KnobType>>}
* @default null
*/
knobs: Array<Partial<KnobType>>;

/**
* If the DrawItem.titleLabel is showing, should the DrawItem.titleLabelBackground
*  be created and placed behind the titleLabel?
*  
*  This defaults to true for DrawSectors and shapes that are not commonly filled
*  (e.g. DrawLines).
* @type {boolean}
* @default true
*/
showTitleLabelBackground: boolean;

/**
* Rotation in degrees about the DrawSector.centerPoint of the DrawSector.
*  The positive direction is clockwise.
* @type {Float}
* @default "0.0"
*/
rotation: Float;

/**
* Center point of the sector
* @type {Point}
* @default "[0,0]"
*/
centerPoint: Point;

/**
* Start angle of the sector in degrees. Default of 0.0 will create a sector that starts
*  with a line from the DrawSector.centerPoint and extends to the right for the indicated
*  DrawSector.radius, then sweeps clockwise toward the DrawSector.endAngle.
* @type {Float}
* @default "0.0"
*/
startAngle: Float;

/**
* End angle of the sector in degrees.
* @type {Float}
* @default "20.0"
*/
endAngle: Float;

/**
* Radius of the sector.
* @type {Distance}
* @default "100"
*/
radius: Distance;





/**
*  Calculates the midpoint coordinates of the circular arc of the sector defined by the
*  given centerPoint, startAngle, endAngle, and radius. The formula for this point is:
*  
*  var averageAngle = (startAngle + endAngle) / 2; // in degrees
* [centerX + radius * cosdeg(averageAngle), centerY + radius * sindeg(averageAngle)]
*  
* 
* @param {Double} X coordinate of the center point of the sector.
* @param {Double} Y coordinate of the center point of the sector.
* @param {Double} start angle of the sector in degrees.
* @param {Double} end angle of the sector in degrees.
* @param {Double} radius of the sector.
*/
static getArcMidpoint(centerX:Double, centerY:Double, startAngle:Double, endAngle:Double, radius:Double): Point;



/**
*  Returns the centerPoint endPoint
* 
*/
getBoundingBox(): Array<Partial<Double>>;

/**
*  Returns the sector's DrawSector.centerPoint.
* 
*/
getCenter(): Point;

/**
*  Calculates the coordinates of the midpoint of this DrawSector's circular arc. The formula
*  for this point is:
*  
*  var averageAngle = (startAngle + endAngle) / 2; // in degrees
* [centerX + radius * cosdeg(averageAngle), centerY + radius * sindeg(averageAngle)]
*  
* 
*/
getArcMidpoint(): Point;

/**
*  Change the center point for this sector.
* 
* @param {Coordinate} X coordinate of the center point (in the global coordinate system).
* @param {Coordinate} Y coordinate of the center point (in the global coordinate system.
*/
setCenterPoint(left:Coordinate, top:Coordinate): void;

/**
*  Move the DrawSector by the specified amounts.
* 
* @param {Distance} number of pixels to move by horizontally
* @param {Distance} number of pixels to move by vertically
*/
moveBy(x:Distance, y:Distance): void;




}

/**
* Chooses one or another next process element based on AdvancedCriteria applied to
*  Process.state.
*  
*  If the AdvancedCriteria evaluate to true, the XORGateway.nextElement is
*  chosen, otherwise the XORGateway.failureElement.
*  
*  Note that "XOR" in XORGateway means "exclusive or" - only one next element is
*  chosen.
*/
class XORGateway extends ProcessElement {
/**
* Creates a new XORGateway
* 
* @param typeCheckedProperties {Partial<XORGateway>=} Object literal containing init properties that will be checked against the class field types.
* @param uncheckedProperties {Object} Object literal containing init properties that will not be checked against the class field types.
* @return {XORGateway} The new instance
*/
static create(typeCheckedProperties? : Partial<XORGateway>, uncheckedProperties?: Object): XORGateway;


/**
* Simple or AdvancedCriteria to be applied against the Process.state.
*  
*  Data values in this criteria prefixed with "$" will be treated as dynamic expressions
*  as detailed in taskInputExpression. Specifically, this means that for 
*  simple criteria, any property value that is a String and is prefixed with "$" will be
*  assumed to be an expression, and for AdvancedCriteria, the same treatment will be
*  applied to Criterion.value.
*  
*  Note that dynamic expressions starting with "$input" are not applicable
*  for an XORGateway but "$inputRecord" can be used for direct reference to Process.state. 
*  
*  This property supports dynamicCriteria - use Criterion.valuePath
*  to refer to values in the Process.ruleScope.
* @type {Criteria}
* @default null
*/
criteria: Criteria;

/**
* Next Process.sequences or Process.elements to execute
*  if the criteria match the process state. 
*  
*  nextElement does not need to be specified if this gateway is part of a
*  Process.sequences and has a next element in the sequence.
*  
*  Note that if there is both a sequence and a normal element
*  with the same name in the current Process, the sequence will
*  be used.
* @type {string}
* @default null
*/
nextElement: string;

/**
* ID of the next sequence or element to proceed to if the criteria do not match.
* @type {string}
* @default null
*/
failureElement: string;










}

/**
* Class for encoding objects as JSON strings.
*/
class JSONEncoder extends Class {
/**
* Creates a new JSONEncoder
* 
* @param typeCheckedProperties {Partial<JSONEncoder>=} Object literal containing init properties that will be checked against the class field types.
* @param uncheckedProperties {Object} Object literal containing init properties that will not be checked against the class field types.
* @return {JSONEncoder} The new instance
*/
static create(typeCheckedProperties? : Partial<JSONEncoder>, uncheckedProperties?: Object): JSONEncoder;


/**
* Controls the output of the JSONEncoder when instances of SmartClient classes (eg a ListGrid)
*  are included in the data to be serialized. See JSONInstanceSerializationMode.
*  
*  Note that the JSONEncoder does not support a format that will recreate the instance if
*  passed to decode() or eval().
* @type {JSONInstanceSerializationMode}
* @default "long"
*/
serializeInstances: JSONInstanceSerializationMode;

/**
* If true, don't show SmartClient internal properties when encoding and object.
* @type {boolean}
* @default false
*/
skipInternalProperties: boolean;

/**
* If objects that cannot be serialized to JSON are encountered during serialization, show a
*  placeholder rather than just omitting them. 
*  
*  The resulting String will not be valid JSON and so cannot be decoded/eval()'d
* @type {boolean}
* @default false
*/
showDebugOutput: boolean;

/**
* Format for encoding JavaScript Date values in JSON. See JSONDateFormat for
*  valid options, or override JSONEncoder.encodeDate to do something custom.
* @type {JSONDateFormat}
* @default "xmlSchema"
*/
dateFormat: JSONDateFormat;

/**
* By default, obscure non-printable characters such as DC3 (Device Control 3, U+0013 hexadecimal)
*  will be escaped according to JSON standards. ECMA-404 / The JSON Data Interchange Format
*  requires the quotation mark (U+0022), reverse solidus (U+005C), and control characters (U+0000
*  through U+001F) to be escaped.
*  
*  These characters are very rarely used in JSON data in web applications. If you know that
*  your application does not use such characters in JSON data, there can be a performance
*  advantage to setting escapeNonPrintable to false in order to disable the
*  logic for escaping these characters. This is a detectable difference only when dealing
*  with very large JSON structures on older browsers that do not provide native support (for
*  example, Internet Explorer 8).
* @type {boolean}
* @default true
*/
escapeNonPrintable: boolean;

/**
* Whether all property names should be quoted, or only those property names that are not valid
*  identifiers or are JavaScript reserved words (such as "true").
*  
*  Encoding only where required produces slightly shorter, more readable output which is still
*  compatible with JavaScript's eval():
*  
*  {
*    someProp : "someValue",
*    "true" : "otherValue",
*    otherProp : "otherValue"
*  }
*  
*  .. but is not understood by many server-side JSON parser implementations.
* @type {boolean}
* @default true
*/
strictQuoting: boolean;

/**
* What the JSONEncoder should do if it encounters a circular reference.
* @type {JSONCircularReferenceMode}
* @default "path"
*/
circularReferenceMode: JSONCircularReferenceMode;

/**
* The string marker used to represent circular references. See JSONEncoder.circularReferenceMode.
* @type {string}
* @default "$$BACKREF$$"
*/
circularReferenceMarker: string;

/**
* Whether to add indentation to the returned JSON string. This makes the returned JSON much
*  easier to read but adds size. Note that when delivering JSON responses compressed, the size
*  difference between prettyPrinted JSON and normal JSON is negligible.
* @type {boolean}
* @default true
*/
prettyPrint: boolean;







/**
*  Serialize an object as a JSON string.
*  
*  Automatically handles circular references - see JSONEncoder.circularReferenceMode.
*  
*  
*  Note that using the String produced by this API with JSON.decode will not
*  successfully preserve dates. Use JSONEncoder.dateFormat "dateConstructor" or
*  "logicalDateConstructor" to have dates round-trip properly.
* 
* 
* @param {any} object to serialize
*/
encode(object:any): string;

/**
*  Encode a JavaScript Date value.
*  
*  By default, follows the JSONEncoder.dateFormat setting. Override to do
*  custom encoding.
*  
* 
* @param {Date} JavaScript date object to be serialized
*/
encodeDate(theDate:Date): string;




}





